// Parse the binary file content into a usable object
const raw = items[0].binary.data.data;
const decoded = Buffer.from(raw, 'base64').toString('utf-8');
const updates = JSON.parse(decoded);

return [{ json: { updates } }];

const raw = items[0].binary.data.data;
const decoded = Buffer.from(raw, 'base64').toString('utf-8');
const content = JSON.parse(decoded);

// Basic required field check
const required = ['subject_line', 'preview_text', 'nyc_updates', 'main_insight', 'feature_title', 'feature_body', 'quick_tips', 'cta_text'];
const missing = required.filter(f => !(f in content));
if (missing.length > 0) {
  throw new Error('Missing required fields: ' + missing.join(', '));
}

return [{ json: { content, valid: true } }];

const output = items[0].json;
const timestamp = new Date().toISOString();
const log = {
  status: 'success',
  timestamp,
  message: 'Newsletter HTML preview generated.',
  stdout: output.stdout || '',
  stderr: output.stderr || ''
};
console.log(JSON.stringify(log, null, 2));
return [{ json: log }];
